oxy_webhelp_navlinks = {"irec_strategy-d39536e60700":{"topics":[{"title":"Factors influencing identity recovery time objectives","shortdesc":"<p class=\"shortdesc\">Environmental and technical factors influence the time required to recover identities         from Active Directory and Microsoft Entra ID snapshots.<\/p>","href":"identity_recovery\/irec_rto_factors.html","attributes":{"data-id":"irec_rto_factors"},"menu":{"hasChildren":false},"tocID":"irec_rto_factors-d39536e60716","topics":[]},{"title":"Identifier persistence during identity recovery","shortdesc":"<p class=\"shortdesc\">The identity recovery method determines whether the original identifier is preserved         or a new identifier is generated, impacting object permissions and         relationships.<\/p>","href":"identity_recovery\/irec_identifier_persistence.html","attributes":{"data-id":"irec_identifier_persistence"},"menu":{"hasChildren":false},"tocID":"irec_identifier_persistence-d39536e60727","topics":[]}]}};